return ['domain'=>'woocommerce-multilingual','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'WPML Multilingual & Multicurrency for WooCommerce 5.6.0','pot-creation-date'=>'2026-09-12T13:36:01+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Multilingual & Multicurrency for WooCommerce'=>'WPML Multilingual & Multicurrency for WooCommerce','https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml','Make your store multilingual and enable multiple currencies | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">Documentation</a>'=>'Зробіть свій магазин багатомовним та увімкніть мультивалютність | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">Документація</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Language of the content to read.'=>'Мова вмісту для читання.','Currency for the returned prices.'=>'Валюта для повернутих цін.','WPML Multilingual & Multicurrency for WooCommerce detected an active cache plugin on your site.'=>'WPML Multilingual & Multicurrency for WooCommerce виявив активний плагін кешування на вашому сайті.','Caching may cause currency display issues for your customers if you are using the multicurrency feature.'=>'Кешування може спричинити проблеми з відображенням валюти для ваших клієнтів, якщо ви використовуєте функцію мультивалютності.','To avoid this, set your cache plugin to not cache pages for visitors that have a cookie set in their browser.'=>'Щоб уникнути цього, налаштуйте плагін кешування так, щоб він не кешував сторінки для відвідувачів, у браузері яких встановлено cookie.','Important: Action Needed for Your <b>Currency Switcher</b>'=>'Важливо: потрібна дія для вашого <b>перемикача валют</b>','We detected that your site is using a <b>Currency Switcher</b> built with Twig templates. For security reasons, support for Twig-based templates will be discontinued in the upcoming version of WPML Multilingual & Multicurrency for WooCommerce 5.6.'=>'Ми виявили, що ваш сайт використовує <b>перемикач валют</b>, побудований на шаблонах Twig. З міркувань безпеки підтримка шаблонів на основі Twig буде припинена в наступній версії WPML Multilingual & Multicurrency for WooCommerce 5.6.','To ensure your <b>Currency Switcher</b> continues working smoothly:'=>'Щоб ваш <b>перемикач валют</b> продовжував працювати належним чином:','- Switch to a PHP-based template - you can select one from the %1$sconfiguration page%2$s.'=>'- Перейдіть на шаблон на основі PHP — ви можете вибрати його на %1$sсторінці конфігурації%2$s.','- Need a custom solution? %1$sContact our support%2$s - we’re here to help you migrate safely.'=>'- Потрібне індивідуальне рішення? %1$sЗверніться до нашої служби підтримки%2$s — ми тут, щоб допомогти вам безпечно виконати міграцію.','We recommend updating your <b>Currency Switcher</b> as soon as possible to avoid disruptions when the new version of WPML Multilingual & Multicurrency for WooCommerce is released.'=>'Ми рекомендуємо оновити ваш <b>перемикач валют</b> якомога швидше, щоб уникнути перебоїв у роботі після виходу нової версії WPML Multilingual & Multicurrency for WooCommerce.','Migrating your multilingual shop? With %s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Переносите свій багатомовний магазин? За допомогою %s ви можете перенести свій перекладений вміст на новий сайт, включаючи перехресні продажі, додаткові продажі та атрибути товарів.','Looking to import your multilingual shop? With %1$s and %2$s in both your original and new site, you can export and import your translations automatically.'=>'Хочете імпортувати свій багатомовний магазин? Маючи %1$s та %2$s як на оригінальному, так і на новому сайті, ви можете автоматично експортувати та імпортувати свої переклади.','WPML Export and Import'=>'WPML Export and Import','You haven\'t added any secondary currencies'=>'Ви не додали жодної додаткової валюти','Please add another currency to fully utilize multicurrency mode. If you do not need multiple currencies, you can disable this setting to improve your site\'s performance.'=>'Будь ласка, додайте іншу валюту, щоб повноцічно використовувати мультивалютний режим. Якщо вам не потрібно кілька валют, ви можете вимкнути це налаштування, щоб покращити продуктивність вашого сайту.','Configure multicurrency mode'=>'Налаштувати мультивалютний режим','Review WPML Multilingual & Multicurrency for WooCommerce'=>'Написати відгук про WPML Multilingual & Multicurrency for WooCommerce','Congrats on making your first multicurrency sale!'=>'Вітаємо з першим продажем у мультивалютному режимі!','Want to help <strong>WPML Multilingual & Multicurrency for WooCommerce</strong> plugin? %1$sGive us a review%2$s!'=>'Хочете допомогти плагіну <strong>WPML Multilingual & Multicurrency for WooCommerce</strong>? %1$sЗалиште нам відгук%2$s!','Currency - no orders found'=>'Валюта — замовлень не знайдено','Invalid nonce'=>'Недійсний nonce','WPML synced translations for product-level changes only.'=>'WPML синхронізував переклади лише для змін на рівні товару.','WPML synced translations for %1$d of %2$d variations.'=>'WPML синхронізував переклади для %1$d з %2$d варіацій.','%d other variation was not checked because its data didn\'t change here.'=>'%d інша варіація не була перевірена, оскільки її дані тут не змінилися.' . "\0" . '%d інші варіації не були перевірені, оскільки їхні дані тут не змінилися.' . "\0" . '%d інших варіацій не були перевірені, оскільки їхні дані тут не змінилися.','If you\'ve made changes <strong>outside this editor</strong> (for example, retranslating an attribute term), use <em>%s</em> below to make sure every translation is current.'=>'Якщо ви внесли зміни <strong>поза цим редактором</strong> (наприклад, переклали термін атрибута заново), скористайтеся кнопкою <em>«%s»</em> нижче, щоб переконатися, що кожен переклад є актуальним.','Force update all'=>'Примусово оновити все','Force update all variation translations'=>'Примусово оновити переклади всіх варіацій','You can switch to <em>"Always check all variations"</em> on the %s.'=>'Ви можете переключитися на <em>«Завжди перевіряти всі варіації»</em> на %s.','WCML Settings page'=>'сторінці налаштувань WCML','(opens in a new tab)'=>'(відкривається в новій вкладці)','Syncing all variations…'=>'Синхронізація всіх варіацій…','Done — all variations synced'=>'Готово — усі варіації синхронізовано','Sync completed for product #%d.'=>'Синхронізацію завершено для товару №%d.','Failed — see console'=>'Помилка — дивіться консоль','Error — '=>'Помилка — ','Dismiss'=>'Закрити','WPML verified %1$d variation × %2$d language on this save. None of them had changes that needed syncing.'=>'WPML перевірив %1$d варіацію × %2$d мову під час цього збереження. Жодна з них не мала змін, що потребували б синхронізації.' . "\0" . 'WPML перевірив %1$d варіації × %2$d мови під час цього збереження. Жодна з них не мала змін, що потребували б синхронізації.' . "\0" . 'WPML перевірив %1$d варіацій × %2$d мови під час цього збереження. Жодна з них не мала змін, що потребували б синхронізації.','That\'s wasted work. Switching to <em>"Only sync variations edited in the editor"</em> would make saves like this much faster — WPML will only sync the variations you actually changed and tell you what was skipped.'=>'Це марна робота. Перемикання на <em>«Синхронізувати лише варіації, відредаговані в редакторі»</em> значно пришвидшить подібні збереження — WPML синхронізуватиме лише ті варіації, які ви насправді змінили, і повідомлятиме, що було пропущено.','You can switch on the %s.'=>'Ви можете змінити це на %s.','Don\'t show this again on this site'=>'Більше не показувати це на цьому сайті','Variation translation sync on product save'=>'Синхронізація перекладу варіацій при збереженні товару','Choose how WPML updates variation translations when you save a variable product. Affects saves in the WooCommerce product editor only — Translation Dashboard and Translate Everything Automatically always run a complete sync.'=>'Виберіть, як WPML має оновлювати переклади варіацій під час збереження варіативного товару. Впливає лише на збереження в редакторі товарів WooCommerce — Панель перекладу та автоматичний переклад завжди виконують повну синхронізацію.','Choose how WPML updates variation translations when you save a variable product.'=>'Виберіть, як WPML має оновлювати переклади варіацій під час збереження варіативного товару.','Affects saves in the WooCommerce product editor only. <b>Translation Dashboard</b> and <b>Translate Everything</b> Automatically always run a complete sync.'=>'Впливає лише на збереження в редакторі товарів WooCommerce. <b>Панель перекладу</b> та <b>Автоматичний переклад</b> завжди виконують повну синхронізацію.','Always check all variations'=>'Завжди перевіряти всі варіації','On every save, WPML checks every variation in every language and syncs anything that\'s out of date.'=>'При кожному збереженні WPML перевіряє кожну варіацію кожною мовою та синхронізує все, що застаріло.','Only sync variations edited in the editor'=>'Синхронізувати лише варіації, відредаговані в редакторі','WPML syncs only the variations changed in this save. After each save, WPML shows what was synced and offers a one-click full sync.'=>'WPML синхронізує лише ті варіації, які були змінені під час цього збереження. Після кожного збереження WPML показує, що було синхронізовано, і пропонує повну синхронізацію в один клік.','To translate custom WooCommerce email notifications, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти власні сповіщення WooCommerce електронною поштою, перейдіть на %1$sПанель перекладу%2$s.','Monthly on the %s'=>'Щомісяця %s числа','Weekly on %s'=>'Щотижня у %s','Cannot get exchange rates. Connection failed.'=>'Не вдалося отримати курси валют. Помилка з\'єднання.','Please note that the payment will be made in %1$s. Your total will be approximately %2$s, depending on the current exchange rate.'=>'Зверніть увагу, що оплата буде здійснена в %1$s. Ваша загальна сума становитиме приблизно %2$s, залежно від поточного курсу валют.','Not yet supported'=>'Ще не підтримується','Set the currency in which your customer will see the final price when they checkout. Choose which accounts they will see in their payment message.'=>'Встановіть валюту, у якій клієнт бачитиме кінцеву ціну під час оформлення замовлення. Виберіть, які рахунки він бачитиме в повідомленні про оплату.','Currency'=>'Валюта','Bank Account'=>'Банківський рахунок','All Accounts'=>'Усі рахунки','All in selected currency'=>'Усі у вибраній валюті','PayPal Email'=>'PayPal email','Merchant ID'=>'ID продавця','Client ID'=>'ID клієнта','Secret Key'=>'Секретний ключ','This gateway does not support %s. To show this gateway please select another currency.'=>'Цей шлюз не підтримує %s. Щоб відобразити цей шлюз, виберіть іншу валюту.','WPML could not read this payment from PayPal, so no refund was sent. Please try the refund again.'=>'WPML не вдалося зчитати цей платіж із PayPal, тому відшкодування не було надіслано. Будь ласка, спробуйте виконати відшкодування ще раз.','The refund amount is too small to send to PayPal in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'Сума відшкодування занадто мала для надсилання в PayPal у валюті платежу, тому відшкодування не було надіслано. Відшкодуйте більшу суму або зафіксуйте відшкодування вручну у WooCommerce.','WPML could not work out how much to refund on this order, so no refund was sent. Check the exchange rate for the order\'s currency in WPML\'s multicurrency settings, then try the refund again.'=>'WPML не вдалося розрахувати суму відшкодування для цього замовлення, тому відшкодування не було надіслано. Перевірте обмінний курс для валюти замовлення в налаштуваннях мультивалютності WPML, а потім спробуйте виконати відшкодування ще раз.','Live Publishable Key'=>'Публічний ключ (Live)','Live Secret Key'=>'Секретний ключ (Live)','Test Publishable Key'=>'Публічний ключ (Test)','Test Secret Key'=>'Секретний ключ (Test)','Connect with Stripe'=>'Підключитися через Stripe','Connect a test account'=>'Підключити тестовий акаунт','Reconnect with Stripe'=>'Перепідключитися через Stripe','Reconnect the test account'=>'Перепідключити тестовий акаунт','Connected with Stripe'=>'Підключено через Stripe','You will continue on Stripe. Save your changes first. Anything unsaved on this screen is lost.'=>'Ви продовжите на Stripe. Спочатку збережіть зміни. Усі незбережені дані на цьому екрані буде втрачено.','Stripe could not be connected. Please try again.'=>'Не вдалося підключити Stripe. Будь ласка, спробуйте ще раз.','This payment is already refunded in full on Stripe, so no refund was sent. Record the refund manually in WooCommerce instead.'=>'Цей платіж уже повністю відшкодовано у Stripe, тому відшкодування не було надіслано. Натомість зафіксуйте відшкодування вручну у WooCommerce.','The refund amount is too small to send to Stripe in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'Сума відшкодування занадто мала для надсилання в Stripe у валюті платежу, тому відшкодування не було надіслано. Відшкодуйте більшу суму або зафіксуйте відшкодування вручну у WooCommerce.','WPML could not read this payment from Stripe, so no refund was sent. Please try the refund again.'=>'WPML не вдалося зчитати цей платіж із Stripe, тому відшкодування не було надіслано. Будь ласка, спробуйте виконати відшкодування ще раз.','PayPal took this payment in %1$s, and WooCommerce can only send a refund in %2$s. Refund this order in your PayPal account, then record it here with "Refund manually".'=>'PayPal прийняв цей платіж у %1$s, а WooCommerce може надіслати відшкодування лише у %2$s. Поверніть кошти за це замовлення у своєму акаунті PayPal, а потім зафіксуйте це тут за допомогою «Відшкодувати вручну».','Language'=>'Мова','Costs and values in custom currencies'=>'Витрати та значення в користувацьких валютах','WPML Multilingual & Multicurrency for WooCommerce by default will multiply all your costs and values defined above by currency exchange rates. If you don\'t want this and you prefer static values instead, you can define them here.'=>'WPML Multilingual & Multicurrency for WooCommerce за замовчуванням множитиме всі ваші витрати та значення, визначені вище, на курси обміну валют. Якщо ви цього не хочете і віддаєте перевагу статичним значенням, ви можете визначити їх тут.','Enable costs in custom currencies'=>'Увімкнути витрати в користувацьких валютах','Calculate shipping costs in other currencies automatically'=>'Розраховувати вартість доставки в інших валютах автоматично','Set shipping costs in other currencies manually'=>'Встановлювати вартість доставки в інших валютах вручну','The label for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.Minimal order amount in %s'=>'Мінімальна сума замовлення в %s','The description for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.The minimal order amount if customer choose %s as a purchase currency.'=>'Мінімальна сума замовлення, якщо клієнт вибере %s як валюту покупки.','Your shipping class %1$s has been created in %2$s language. Please switch your language if you want to provide shipping costs in different currencies for this class.'=>'Ваш клас доставки %1$s створено мовою %2$s. Будь ласка, змініть мову, якщо ви хочете вказати вартість доставки в різних валютах для цього класу.','"%1$s" shipping class cost in %2$s'=>'Вартість класу доставки «%1$s» у %2$s','N/A'=>'Н/Д','No shipping class cost in %s'=>'Немає вартості класу доставки в %s','The label for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.Cost in %s'=>'Вартість у %s','The description for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.The shipping cost if customer choose %s as a purchase currency.'=>'Вартість доставки, якщо клієнт вибере %s як валюту покупки.','Your site needs HTTPS to connect a live Stripe account. You can still connect a test account.'=>'Вашому сайту потрібен HTTPS для підключення реального акаунта Stripe. Ви все ще можете підключити тестовий акаунт.','Stripe did not return a connection link. Please try again.'=>'Stripe не повернув посилання для підключення. Будь ласка, спробуйте ще раз.','Stripe is now connected for %s.'=>'Stripe тепер підключено для %s.','Stripe could not be connected for %s. Please try again.'=>'Не вдалося підключити Stripe для %s. Будь ласка, спробуйте ще раз.','Currencies'=>'Валюти','Add currency'=>'Додати валюту','Rate'=>'Курс','default'=>'типово','Edit'=>'Редагувати','Currency displayed first'=>'Валюта, що відображається першою','Choose which currency to display when a client switches languages'=>'Виберіть, яку валюту відображати, коли клієнт змінює мову','Keep'=>'Залишити','Delete'=>'Видалити','Currencies to display for each language'=>'Валюти для відображення для кожної мови','Add a secondary currency to choose which currencies appear for each language.'=>'Додайте додаткову валюту, щоб вибрати, які валюти з\'являтимуться для кожної мови.','Enable %1$s for %2$s'=>'Увімкнути %1$s для %2$s','Disable %1$s for %2$s'=>'Вимкнути %1$s для %2$s','Settings'=>'Налаштування','Add new currency'=>'Додати нову валюту','Currency settings for %s'=>'Налаштування валюти для %s','Select currency'=>'Виберіть валюту','Exchange Rate'=>'Курс валют','Only numeric'=>'Тільки цифри','(previous value: %s)'=>'(попереднє значення: %s)','Currency Preview'=>'Попередній перегляд валюти','Currency Position'=>'Позиція валюти','Left'=>'Зліва','Right'=>'Справа','Left with space'=>'Зліва з пробілом','Right with space'=>'Справа з пробілом','Thousand Separator'=>'Розділювач тисяч','(Space)'=>'(пробіл)','Decimal Separator'=>'Десятковий розділювач','Number of Decimals'=>'Кількість десяткових знаків','Rounding to the nearest integer'=>'Округлення до найближчого цілого числа','Disabled'=>'Вимкнено','Up'=>'Вгору','Down'=>'Вниз','Nearest'=>'До найближчого','Increment for nearest integer'=>'Крок для найближчого цілого числа','The resulting price will be an increment of this value after initial rounding.%se.g.:'=>'Кінцева ціна буде кратною цьому значенню після початкового округлення.%sнапр.:','1454.07 &raquo; 1454 when set to 1'=>'1454.07 &raquo; 1454 при значенні 1','1454.07 &raquo; 1450 when set to 10'=>'1454.07 &raquo; 1450 при значенні 10','1454.07 &raquo; 1500 when set to 100'=>'1454.07 &raquo; 1500 при значенні 100','Round the converted price to the closest integer. %se.g. 15.78 becomes 16.00'=>'Округлити конвертовану ціну до найближчого цілого числа. %sнапр. 15.78 стає 16.00','The value to be subtracted from the amount obtained previously.'=>'Значення, яке буде віднято від суми, отриманої раніше.','For 1454.07, when the increment for the nearest integer is 100 and the auto-subtract amount is 1, the resulting amount is 1499.'=>'Для 1454.07, якщо крок для найближчого цілого числа дорівнює 100, а сума автоматичного віднімання — 1, кінцева сума становитиме 1499.','Autosubtract amount'=>'Сума автоматичного віднімання','Payment Gateways'=>'Платіжні шлюзи','Custom settings for %s'=>'Спеціальні налаштування для %s','Learn more'=>'Дізнатися більше','Please enter a valid number'=>'Будь ласка, введіть коректне число','The currency was not saved. Try again.'=>'Валюту не було збережено. Спробуйте ще раз.','The setting was not saved. Try again.'=>'Налаштування не було збережено. Спробуйте ще раз.','Cancel'=>'Скасувати','Save'=>'Зберегти','Currency available in'=>'Валюта доступна в','All countries'=>'Усі країни','All countries except: '=>'Усі країни, крім: ','All countries except...'=>'Усі країни, крім...','Specific countries'=>'Конкретні країни','Show currencies based on'=>'Показувати валюти на основі','You need the WPML plugin to make your store multilingual and display currencies based on site language. Don\'t have it yet?'=>'Вам потрібен плагін WPML, щоб зробити ваш магазин багатомовним і відображати валюти на основі мови сайту. Ще не маєте його?','Purchase WPML now'=>'Придбати WPML зараз','Site Language'=>'Мова сайту','Client Location'=>'Місцезнаходження клієнта','Location based'=>'На основі місцезнаходження','WooCommerce integrates with MaxMind Geolocation to reliably determine the location of your customers.'=>'WooCommerce інтегрується з MaxMind Geolocation для надійного визначення місцезнаходження ваших клієнтів.','Great! Now you can use Geolocation to determine default currency for chosen languages. You can edit that key in '=>'Чудово! Тепер ви можете використовувати геолокацію для визначення типової валюти для вибраних мов. Ви можете змінити цей ключ на ','WooCommerce settings page.'=>'сторінці налаштувань WooCommerce.','MaxMind Licence Key'=>'Ліцензійний ключ MaxMind','Apply'=>'Застосувати','Please note: without a free MaxMind key, your geolocation calls will be limited and your site performance may be impacted.'=>'Зверніть увагу: без безкоштовного ключа MaxMind ваші запити геолокації будуть обмежені, що може вплинути на продуктивність вашого сайту.','Learn how to generate a free license key'=>'Дізнайтеся, як створити безкоштовний ліцензійний ключ','Set on %s'=>'Встановлено %s','Country availability'=>'Доступність по країнах','All countries except'=>'Усі країни, крім','Configure per country availability for this payment gateway'=>'Налаштувати доступність для цього платіжного шлюзу по країнах','Save changes'=>'Зберегти зміни','Settings saved.'=>'Налаштування збережено.','Error saving settings.'=>'Помилка під час збереження налаштувань.','We noticed that you\'re using WooCommerce Gateways Country Limiter plugin which is now integrated into WPML Multilingual & Multicurrency for WooCommerce. Please remove it!'=>'Ми помітили, що ви використовуєте плагін WooCommerce Gateways Country Limiter, який тепер інтегровано в WPML Multilingual & Multicurrency for WooCommerce. Будь ласка, видаліть його!','To translate custom text for payment methods, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти власний текст для методів оплати, перейдіть на %1$sПанель перекладу%2$s.','To translate permalinks for product taxonomies, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'Щоб перекласти постійні посилання для таксономій товарів, перейдіть у %1$sWPML Multilingual & Multicurrency for WooCommerce → Ярлики магазину%2$s.','To translate product permalinks, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'Щоб перекласти постійні посилання товарів, перейдіть у %1$sWPML Multilingual & Multicurrency for WooCommerce → Ярлики магазину%2$s.','How to translate permalinks for product taxonomies'=>'Як перекласти постійні посилання для таксономій товарів','How to translate product permalinks'=>'Як перекласти постійні посилання товарів','Translate WooCommerce products'=>'Перекласти товари WooCommerce','Translate shipping classes'=>'Перекласти класи доставки','Configure multicurrency for multilingual sites'=>'Налаштувати мультивалютність для багатомовних сайтів','Translate endpoints'=>'Перекласти кінцеві точки','How to translate this?'=>'Як це перекласти?','WPML Multilingual & Multicurrency for WooCommerce will use cookies to understand the basket info when using languages in domains and to transfer data between the domains.'=>'WPML Multilingual & Multicurrency for WooCommerce використовуватиме файли cookie, щоб розуміти інформацію про кошик при використанні мов у доменах та для передачі даних між доменами.','WPML Multilingual & Multicurrency for WooCommerce will also use cookies to identify the language and currency of each customer’s order as well as the currency of the reports created by WooCommerce. WPML Multilingual & Multicurrency for WooCommerce extends these reports by adding the currency’s information.'=>'WPML Multilingual & Multicurrency for WooCommerce також використовуватиме файли cookie для ідентифікації мови та валюти замовлення кожного клієнта, а також валюти звітів, створених WooCommerce. WPML Multilingual & Multicurrency for WooCommerce розширює ці звіти, додаючи інформацію про валюту.','Invalid currency parameter: "%s"'=>'Недійсний параметр валюти: «%s»','Invalid language parameter: "%s"'=>'Недійсний параметр мови: «%s»','Product not found: %d'=>'Товар не знайдено: %d','Term not found: %d'=>'Термін не знайдено: %d','Using "translation_of" requires providing a "lang" parameter too'=>'Використання «translation_of» вимагає також надання параметра «lang»','Multilingual'=>'Багатомовність','Multicurrency'=>'Мультивалютність','To run your store in multiple languages, you need to use the %1$sWPML plugin%2$s.'=>'Щоб ваш магазин працював кількома мовами, вам потрібно використовувати %1$sплагін WPML%2$s.','If you have it already, install and activate it. Otherwise, %1$sbuy WPML%2$s.'=>'Якщо він у вас уже є, встановіть та активуйте його. В іншому випадку %1$sпридбайте WPML%2$s.','You will need either the Multilingual CMS or Multilingual Agency package to use WPML with WooCommerce.'=>'Для використання WPML з WooCommerce вам знадобиться пакет Multilingual CMS або Multilingual Agency.','You can still use the %1$smulticurrency features%2$s without buying anything.'=>'Ви все ще можете використовувати %1$sфункції мультивалютності%2$s нічого не купуючи.','%s translation'=>'Переклад %s','Translating %1$s? Use the %2$s table for easier translation.'=>'Перекладаєте %1$s? Використовуйте таблицю %2$s для легшого перекладу.','To translate product details, including their taxonomy, use this dashboard. If you need to translate taxonomy independently or adjust store and currency settings, visit: %1$sWPML Multilingual & Multicurrency for WooCommerce documentation%2$s.'=>'Щоб перекласти деталі товару, включаючи їхню таксономію, використовуйте цю панель. Якщо вам потрібно перекласти таксономію окремо або налаштувати параметри магазину та валюти, відвідайте: %1$sдокументацію WPML Multilingual & Multicurrency for WooCommerce%2$s.','To translate this content, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти цей вміст, перейдіть на %1$sПанель перекладу%2$s.','To see how to translate this text, save your changes here first.'=>'Щоб побачити, як перекласти цей текст, спочатку збережіть зміни тут.','Header alignment for translations'=>'Вирівнювання заголовка для перекладів','Automatically align email headers based on%slanguage direction (right-to-left or left-to-right).'=>'Автоматично вирівнювати заголовки електронних листів залежно від%sнапрямку мови (справа наліво або зліва направо).','Off – use the "Header alignment" setting above'=>'Вимк. — використовувати налаштування «Вирівнювання заголовка» вище','On – align automatically'=>'Увімк. — вирівнювати автоматично','Introduction'=>'Вступ','Store Pages'=>'Сторінки магазину','Global Attributes'=>'Глобальні атрибути','Multiple Currencies'=>'Мультивалютність','Tour Data'=>'Дані туру','Title'=>'Заголовок','Content'=>'Вміст','To translate the Method Title, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти назву методу, перейдіть на %1$sПанель перекладу%2$s.','To translate Labels, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти ярлики, перейдіть на %1$sПанель перекладу%2$s.','To translate custom product fields, save your changes here first, then go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти власні поля товарів, спочатку збережіть зміни тут, а потім перейдіть на %1$sПанель перекладу%2$s.','Calculate costs in other currencies automatically'=>'Розраховувати вартість в інших валютах автоматично','Set costs in other currencies manually'=>'Встановлювати вартість в інших валютах вручну','Bookings'=>'Бронювання','Resources Label'=>'Ярлик ресурсів','Resources'=>'Ресурси','Person Types'=>'Типи осіб','Person Type Name'=>'Назва типу особи','Description'=>'Опис','Resources label'=>'Ярлик ресурсів','To translate Resources, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Щоб перекласти ресурси, перейдіть на %1$sПанель перекладу%2$s і надішліть відповідний товар на переклад.','To translate Person Types, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Щоб перекласти типи осіб, перейдіть на %1$sПанель перекладу%2$s і надішліть відповідний товар на переклад.','Booking currency'=>'Валюта бронювання','Composite Products ( Components )'=>'Складені товари ( компоненти )','Name'=>'Назва','Composite Products ( Scenarios )'=>'Складені товари ( сценарії )','To translate global add-ons, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти глобальні додатки, перейдіть на %1$sПанель перекладу%2$s.','Product Add-ons Group "%s"'=>'Група додатків товару «%s»','Placeholder'=>'Заповнювач','Options'=>'Опції','Label'=>'Ярлик','To translate per-product add-ons, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Щоб перекласти додатки для окремих товарів, перейдіть на %1$sПанель перекладу%2$s і надішліть відповідний товар на переклад.','Multi-currency settings'=>'Налаштування мультивалютності','Calculate prices in other currencies automatically'=>'Розраховувати ціни в інших валютах автоматично','Set prices in other currencies manually'=>'Встановлювати ціни в інших валютах вручну','Here you can set different prices for the %s in multiple currencies:'=>'Тут ви можете встановити різні ціни для %s у кількох валютах:','Product Bundles'=>'Пакетні товари','You can translate text for subscription products from the %1$sTranslation Dashboard%2$s.'=>'Ви можете перекласти текст для товарів за підпискою на %1$sПанелі перекладу%2$s.','Subscription Price'=>'Ціна підписки','Sign-up Fee'=>'Плата за реєстрацію','Product tabs'=>'Вкладки товару','Heading'=>'Заголовок','To translate custom per-product tabs, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Щоб перекласти власні вкладки для окремих товарів, перейдіть на %1$sПанель перекладу%2$s і надішліть відповідний товар на переклад.','Custom Tabs'=>'Власні вкладки','Tab Title'=>'Заголовок вкладки','Quick Edit isn\'t available for product translations:'=>'Швидке редагування недоступне для перекладів товарів:','- To edit this product\'s translation, use the %1$sTranslation Dashboard%2$s.'=>'— Щоб редагувати переклад цього товару, скористайтеся %1$sПанеллю перекладу%2$s.','- To edit the original product, switch back to the default language.'=>'— Щоб редагувати оригінальний товар, поверніться до типової мови.','Multilingual Settings'=>'Багатомовні налаштування','Multicurrency Settings'=>'Налаштування мультивалютності','It’s recommended that you translate products from the %1$sTranslation Dashboard%2$s.'=>'Рекомендується перекладати товари на %1$sПанелі перекладу%2$s.','WCML'=>'WCML','Shows a list of the products that existed in the cart before the cart is reset on the front end after switching the language or the currency. It will be hidden when there are no products to show.'=>'Показує список товарів, які були в кошику до його скидання на клієнтській частині після зміни мови або валюти. Віджет буде приховано, якщо немає товарів для показу.','Products before cart reset'=>'Товари до скидання кошика','Switching language?'=>'Змінити мову?','You\'ve switched the language and there are items in the cart. If you keep the %s language, the cart will be emptied and you will have to add the items again to the cart.'=>'Ви змінили мову, а в кошику є товари. Якщо ви залишите мову %s, кошик буде очищено, і вам доведеться додавати товари знову.','Keep %s'=>'Залишити %s','Switch back to %s'=>'Повернутися до %s','Reset cart option warning 1Because of some elements in your site configuration, when the users switch the currency or the language on the front end, the cart content might not be synchronized correctly.'=>'Через деякі елементи конфігурації вашого сайту, коли користувачі змінюють валюту або мову на клієнтській частині, вміст кошика може синхронізуватися некоректно.','Reset cart option warning 2It is recommended that you %s with the option to reset the cart in a situation like this.'=>'Рекомендується %s з опцією скидання кошика в такій ситуації.','configure WPML Multilingual & Multicurrency for WooCommerce'=>'налаштувати WPML Multilingual & Multicurrency for WooCommerce','More details'=>'Детальніше','Switching currency?'=>'Змінити валюту?','Your cart is not empty! After you switched the currency, all items from the cart will be removed and you have to add them again.'=>'Ваш кошик не порожній! Після зміни валюти всі товари з кошика будуть видалені, і вам доведеться додати їх знову.','Keep using %s'=>'Продовжити використовувати %s','Proceed'=>'Продовжити','Show reviews in all languages  (%s)'=>'Показати відгуки всіма мовами (%s)','Show only reviews in %1$s (%2$s)'=>'Показати відгуки лише мовою %1$s (%2$s)','translated'=>'перекладено','Show original'=>'Показати оригінал','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML</a> versions prior %2$s.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює. Він несумісний з версіями <a href="%1$s">WPML</a> старішими за %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. Please finish the installation of WPML first.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює. Будь ласка, спочатку завершіть встановлення WPML.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">Woocommerce</a> versions prior %2$s.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює. Він несумісний з версіями <a href="%1$s">WooCommerce</a> старішими за %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML String Translation</a> versions prior %2$s.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює. Він несумісний з версіями <a href="%1$s">WPML String Translation</a> старішими за %2$s.','WPML support'=>'Підтримка WPML','Default taxonomies must be translatable: 1/6Some taxonomies in your site are forced to be untranslatable. This is causing a problem when you\'re trying to run a multilingual WooCommerce site.'=>'Деякі таксономії на вашому сайті примусово встановлені як такі, що не підлягають перекладу. Це спричиняє проблему під час роботи багатомовного сайту WooCommerce.','Default taxonomies must be translatable: 2/6A plugin or the theme are probably doing this.'=>'Ймовірно, це робить плагін або тема.','Default taxonomies must be translatable: 3/6What you can do:'=>'Що ви можете зробити:','Default taxonomies must be translatable: 4/61. Temporarily disable plugins and see if this message disappears.'=>'1. Тимчасово вимкніть плагіни та перевірте, чи зникне це повідомлення.','Default taxonomies must be translatable: 5/62. Temporarily switch the theme and see if this message disappears.'=>'2. Тимчасово змініть тему та перевірте, чи зникне це повідомлення.','Default taxonomies must be translatable: 6/6It\'s best to contact %s, tell that you\'re getting this message and offer to send a Duplicator copy of the site. We will work with the theme/plugin author and fix the problem for good. In the meanwhile, we\'ll give you a temporary solution, so you\'re not stuck.'=>'Найкраще звернутися в %s, повідомити про це повідомлення та запропонувати надіслати копію сайту, зроблену за допомогою Duplicator. Ми зв’яжемося з автором теми/плагіна та остаточно вирішимо проблему. Тим часом ми надамо вам тимчасове рішення, щоб ви не зупиняли роботу.','and'=>'та','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It requires %s in order to work.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює. Для роботи потрібні %s.','Please %1$sactivate %2$s%3$s.'=>'Будь ласка, %1$sактивуйте %2$s%3$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective.'=>'WPML Multilingual & Multicurrency for WooCommerce увімкнено, але він не працює.','Because this site uses the default permalink structure, you cannot use slug translation for product permalinks.'=>'Оскільки цей сайт використовує типову структуру постійних посилань, ви не можете використовувати переклад частини посилання для постійних посилань товарів.','Please choose a different permalink structure or disable slug translation.'=>'Будь ласка, виберіть іншу структуру постійних посилань або вимкніть переклад частини посилання.','Permalink settings'=>'Налаштування постійних посилань','Configure products slug translation'=>'Налаштувати переклад частини посилання товарів','wpml-config.xml file missing from WPML Multilingual & Multicurrency for WooCommerce folder.'=>'Файл wpml-config.xml відсутній у папці WPML Multilingual & Multicurrency for WooCommerce.','Custom field %s configuration from wpml-config.xml file was altered!'=>'Конфігурацію власного поля %s з файлу wpml-config.xml було змінено!','Custom type %s configuration from wpml-config.xml file was altered!'=>'Конфігурацію власного типу %s з файлу wpml-config.xml було змінено!','Custom taxonomy %s configuration from wpml-config.xml file was altered!'=>'Конфігурацію власної таксономії %s з файлу wpml-config.xml було змінено!','We detected a problem in your WPML configuration: the %1$sproduct_type%2$s taxonomy is set as translatable and this would cause problems with translated products. You can fix this in the %3$sMultilingual Content Setup page%4$s.'=>'Ми виявили проблему у вашій конфігурації WPML: таксономія %1$sproduct_type%2$s встановлена як така, що підлягає перекладу, і це може спричинити проблеми з перекладеними товарами. Ви можете виправити це на %3$sсторінці налаштування багатомовного вмісту%4$s.','We detected that the %1$sproduct_type%2$s field was set incorrectly for some product translations. This happened because the product_type taxonomy was translated. You can fix this in the WPML Multilingual & Multicurrency for WooCommerce %3$stroubleshooting page%4$s.'=>'Ми виявили, що поле %1$sproduct_type%2$s було встановлено неправильно для деяких перекладів товарів. Це сталося через те, що таксономія product_type була перекладена. Ви можете виправити це на %3$sсторінці виправлення неполадок%4$s WPML Multilingual & Multicurrency for WooCommerce.','Downloading translations... Please don\'t close this page.'=>'Завантаження перекладів... Будь ласка, не закривайте цю сторінку.','Order language:'=>'Мова замовлення:','All the products will be removed from the current order in order to change the language'=>'Усі товари будуть видалені з поточного замовлення для зміни мови','Quick edit "%s" inline'=>'Швидко редагувати «%s»','Quick Edit'=>'Швидке редагування','Your settings have been saved.'=>'Ваші налаштування збережено.','You do not have permission to perform this action.'=>'У вас немає прав для виконання цієї дії.','Choose a file'=>'Вибрати файл','At least one of these fields is required: title, content or excerpt'=>'Принаймні одне з цих полів є обов’язковим: заголовок, вміст або уривок','This translation job will no longer be assigned to you. Other translators will be able take it and continue the translation.'=>'Це завдання з перекладу більше не буде закріплено за вами. Інші перекладачі зможуть взяти його та продовжити переклад.','This field is locked for editing because WPML will copy its value from the original language.'=>'Це поле заблоковано для редагування, оскільки WPML скопіює його значення з оригінальної мови.','This is a translation of %1$s. Some of the fields are not editable. It\'s recommended that you translate products from the %2$sTranslation Dashboard%3$s.'=>'Це переклад %1$s. Деякі поля недоступні для редагування. Рекомендується перекладати товари на %2$sПанелі перекладу%3$s.','Cart'=>'Кошик','Checkout'=>'Оформлення замовлення','Checkout &rarr; Pay'=>'Оформлення замовлення &rarr; оплата','Order Received'=>'Замовлення отримано','My Account'=>'Мій акаунт','Change Password'=>'Змінити пароль','Edit My Address'=>'Редагувати мою адресу','Logout'=>'Вийти','Lost Password'=>'Втрачений пароль','View Order'=>'Переглянути замовлення','Shop'=>'Магазин','To quickly translate this and other WooCommerce store pages, please run the %1$ssetup wizard%2$s.'=>'Щоб швидко перекласти цю та інші сторінки магазину WooCommerce, будь ласка, запустіть %1$sмайстер налаштування%2$s.','To translate %1$s please use the %2$s translation%3$s page, inside the %4$sWPML Multilingual & Multicurrency for WooCommerce admin%5$s.'=>'Щоб перекласти %1$s, будь ласка, скористайтеся сторінкою перекладу %2$s%3$s у %4$sадмінпанелі WPML Multilingual & Multicurrency for WooCommerce%5$s.','%d products left'=>'Залишилося товарів: %d','Synchronization complete!'=>'Синхронізацію завершено!','Invalid taxonomy %s'=>'Недійсна таксономія %s','Some translated %1$s have different %2$s assignments.'=>'Деякі перекладені %1$s мають різні призначення %2$s.','Update %1$s for all translated %2$s'=>'Оновити %1$s для всіх перекладених %2$s','All %1$s have the same %2$s assignments.'=>'Усі %1$s мають однакові призначення %2$s.','Successfully updated %1$s for all translated %2$s.'=>'Успішно оновлено %1$s для всіх перекладених %2$s.','Product Base'=>'База товарів','Product Tag Base'=>'База тегів товарів','Product Category Base'=>'База категорій товарів','Product Attribute Base'=>'База атрибутів товарів','Attribute Slug'=>'Частина посилання атрибута','Endpoint: %s'=>'Кінцева точка: %s','You are using the same value as for the regular category base. This is known to create conflicts resulting in urls not working properly.'=>'Ви використовуєте те саме значення, що й для звичайної бази категорій. Відомо, що це створює конфлікти, через які URL-адреси працюють некоректно.','To translate attributes, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Щоб перекласти атрибути, перейдіть на %1$sПанель перекладу%2$s і надішліть відповідний товар на переклад.','The default currency was changed. In order to show accurate prices in all currencies, you need to update the exchange rates under the %1$sMulti-currency%2$s configuration.'=>'Типову валюту було змінено. Щоб показувати точні ціни у всіх валютах, вам потрібно оновити курси валют у налаштуваннях %1$sМультивалютності%2$s.','Show all currencies'=>'Показати всі валюти','Order currency:'=>'Валюта замовлення:','All the products will be removed from the current order in order to change the currency'=>'Усі товари будуть видалені з поточного замовлення для зміни валюти','Currencies order updated'=>'Порядок валют оновлено','Uploads'=>'Завантаження','Currency switcher'=>'Перемикач валют','Customize the currency switcher'=>'Налаштувати перемикач валют','You haven\'t added any secondary currencies.'=>'Ви не додали жодної додаткової валюти.','Use custom settings for translations download files'=>'Використовувати власні налаштування для файлів завантаження перекладів','Use the same files for translations'=>'Використовувати ті самі файли для перекладів','Add separate download files for translations when you translate this product'=>'Додати окремі файли завантаження для перекладів під час перекладу цього товару','You have untranslated terms!'=>'У вас є неперекладені терміни!','Store URLs'=>'URL-адреси магазину','Status'=>'Статус','Troubleshooting'=>'Виправлення неполадок','Translate Products'=>'Перекласти товари','Go to WPML &rarr; Translation Dashboard to translate Products'=>'Перейдіть у WPML &rarr; Панель перекладу, щоб перекласти товари','Translate Taxonomy'=>'Перекласти таксономію','Go to WPML &rarr; Taxonomy Translation to translate Taxonomy terms manually'=>'Перейдіть у WPML &rarr; Переклад таксономій, щоб перекласти терміни таксономії вручну','Prefer to translate manually?'=>'Бажаєте перекладати вручну?','To manually translate products, go to %1$sProducts%2$s and click on the "plus" icon.'=>'Щоб вручну перекласти товари, перейдіть у %1$sТовари%2$s і натисніть на іконку «плюс».','To manually translate product categories, tags and attributes, go to %1$sWPML &rarr; Taxonomy Translation%2$s.'=>'Щоб вручну перекласти категорії, теги та атрибути товарів, перейдіть у %1$sWPML &rarr; Переклад таксономій%2$s.','Translation'=>'Переклад','Translate the WooCommerce slugs (Shop, Product base, etc.) at WPML → Translations → Store URLs.'=>'Перекладіть частини посилання WooCommerce (Магазин, База товарів тощо) у WPML → Переклади → URL-адреси магазину.','Open Store URLs ›'=>'Відкрити URL-адреси магазину ›','Go to WPML → Translations → Dashboard to translate Products.'=>'Перейдіть у WPML → Переклади → Панель, щоб перекласти товари.','Translate Products ›'=>'Перекласти товари ›','Translate product taxonomies'=>'Перекласти таксономії товарів','Go to WPML → Translations → Taxonomy to translate product categories, tags and attributes.'=>'Перейдіть у WPML → Переклади → Таксономія, щоб перекласти категорії, теги та атрибути товарів.','Translate Taxonomies ›'=>'Перекласти таксономії ›','Products, media, downloads, reviews, cart and the variation translation sync — all in WPML → Settings → WCML.'=>'Товари, медіафайли, завантаження, відгуки, кошик і синхронізація перекладу варіацій — усе в WPML → Налаштування → WCML.','Open WCML Settings ›'=>'Відкрити налаштування WCML ›','Configure currencies, exchange rates and currency switchers at WPML → Settings → Multicurrency.'=>'Налаштуйте валюти, курси валют і перемикачі валют у WPML → Налаштування → Мультивалютність.','Open Multicurrency ›'=>'Відкрити Мультивалютність ›','Support'=>'Підтримка','WCML status'=>'Статус WCML','Diagnostic checks for store pages, products, taxonomies, multicurrency and plugins.'=>'Діагностичні перевірки сторінок магазину, товарів, таксономій, мультивалютності та плагінів.','Open WCML status ›'=>'Відкрити статус WCML ›','Fix WCML translations'=>'Виправити переклади WCML','Safe bulk tools to sync product variations, galleries and stock; register missing reviews; create missing attribute translations.'=>'Безпечні інструменти масової синхронізації варіацій товарів, галерей і запасів; реєстрація відсутніх відгуків; створення відсутніх перекладів атрибутів.','Open Fix WCML translations ›'=>'Відкрити Виправити переклади WCML ›','WCML configuration log'=>'Журнал конфігурації WCML','Read-only snapshot of the WCML configuration. Copy when WPML Support asks.'=>'Знімок конфігурації WCML тільки для читання. Скопіюйте, коли запитає підтримка WPML.','Open WCML configuration log ›'=>'Відкрити журнал конфігурації WCML ›','WCML translation maintenance'=>'Обслуговування перекладів WCML','Advanced repair tools — only run when WPML Support asks you to.'=>'Розширені інструменти відновлення — запускайте лише за запитом підтримки WPML.','Open WCML translation maintenance ›'=>'Відкрити обслуговування перекладів WCML ›','WPML is installed on this site, so WCML\'s controls have moved into WPML. Pick the area you need.'=>'На цьому сайті встановлено WPML, тому елементи керування WCML переміщено у WPML. Виберіть потрібний розділ.','Translatable?'=>'Перекладається?','Enable this if you want to translate attribute values with WPML Multilingual & Multicurrency for WooCommerce'=>'Увімкніть це, якщо хочете перекладати значення атрибутів за допомогою WPML Multilingual & Multicurrency for WooCommerce','Existing translations and variations associated will be deleted.'=>'Існуючі переклади та пов’язані варіації будуть видалені.','Products removed after switching to %s:'=>'Товари, видалені після переходу на %s:','Clear list'=>'Очистити список','Products Synchronization'=>'Синхронізація товарів','Configure specific product properties that should be synced to translations.'=>'Налаштуйте конкретні властивості товарів, які мають синхронізуватися з перекладами.','Sync publishing date for translated products.'=>'Синхронізувати дату публікації для перекладених товарів.','Sync products and product taxonomies order.'=>'Синхронізувати порядок товарів і таксономій товарів.','Products Media Synchronization'=>'Синхронізація медіафайлів товарів','Configure thumbnail and gallery synchronization to translations.'=>'Налаштуйте синхронізацію мініатюр і галерей з перекладами.','Display original images on the translated product front page if images not specified'=>'Відображати оригінальні зображення на сторінці перекладеного товару, якщо зображення не вказані','Products Download Files'=>'Файли завантаження товарів','If you are using downloadable products, you can choose to have their paths
                                            synchronized, or seperate for each language.'=>'Якщо ви використовуєте товари для завантаження, ви можете вибрати синхронізацію їхніх шляхів
 або встановити окремі для кожної мови.','Add separate download files for translations when translating products'=>'Додавати окремі файли завантаження для перекладів під час перекладу товарів','Product reviews'=>'Відгуки про товари','Define how to display product reviews on the product page by default. The customer will be still able to filter reviews by language.'=>'Визначте, як типово відображати відгуки про товари на сторінці товару. Клієнт все одно зможе фільтрувати відгуки за мовою.','By default, show reviews in all languages'=>'Типово показувати відгуки всіма мовами','You can choose to clear the cart contents when you change language or currency in case you have problems in cart or checkout page'=>'Ви можете очистити вміст кошика при зміні мови або валюти, якщо у вас виникають проблеми на сторінці кошика або оформлення замовлення','Switching languages when there are items in the cart'=>'Перемикання мов, коли в кошику є товари','Synchronize cart content when switching languages'=>'Синхронізувати вміст кошика при зміні мови','Prompt for a confirmation and reset the cart'=>'Запитувати підтвердження та очищати кошик','Switching currencies when there are items in the cart'=>'Перемикання валют, коли в кошику є товари','Synchronize cart content when switching currencies'=>'Синхронізувати вміст кошика при зміні валюти','This feature was disabled. Please enable %1$sWPML cookies%2$s to continue.'=>'Цю функцію було вимкнено. Будь ласка, увімкніть %1$sкуки WPML%2$s, щоб продовжити.','Not sure which option to choose? Read about %1$spotential issues when switching languages and currencies while the cart has items%2$s.'=>'Не впевнені, який варіант обрати? Прочитайте про %1$sпотенційні проблеми при зміні мови та валюти, коли в кошику є товари%2$s.','Product Translation Interface'=>'Інтерфейс перекладу товарів','The recommended way is using the WPML Translation Editor. It is streamlined for making the translation process much easier while also providing a much better integration with various WooCommerce extensions.'=>'Рекомендований спосіб — використання редактора перекладів WPML. Він оптимізований для значного спрощення процесу перекладу, а також забезпечує набагато кращу інтеграцію з різними розширеннями WooCommerce.','WPML Translation Editor'=>'Редактор перекладів WPML','Native WooCommerce product editing screen'=>'Стандартний екран редагування товарів WooCommerce','If you are using a page builder to design WooCommerce products, you should only use WPML\'s Translation Editor.'=>'Якщо ви використовуєте конструктор сторінок для дизайну товарів WooCommerce, вам слід використовувати лише редактор перекладів WPML.','OK (translate with the WordPress editor)'=>'ОК (перекладати в редакторі WordPress)','Cancel (stay with the Translation Editor)'=>'Скасувати (залишити редактор перекладів)','Set different slugs in different languages for %s on WPML Multilingual & Multicurrency for WooCommerce URLs translations page'=>'Встановіть різні частини посилання різними мовами для %s на сторінці перекладу URL-адрес WPML Multilingual & Multicurrency for WooCommerce','To translate the attribute slug, please set the option "Enable archives?" for the attribute %s in WooCommerce'=>'Щоб перекласти частину посилання атрибута, будь ласка, встановіть опцію «Увімкнути архіви?» для атрибута %s у WooCommerce','Synchronize attributes and update product variations'=>'Синхронізувати атрибути та оновити варіації товарів','This will automatically generate variations for translated products corresponding to recently translated attributes.'=>'Це автоматично створить варіації для перекладених товарів, що відповідають нещодавно перекладеним атрибутам.','Currently, there are %s variations that need to be created.'=>'Наразі потрібно створити %s варіацій.','Synchronize %s assignment in content'=>'Синхронізувати призначення %s у контенті','This action lets you automatically apply the %s taxonomy to your content in different languages. It will scan the original content and apply the same taxonomy to translated content.'=>'Ця дія дозволяє автоматично застосувати таксономію %s до вашого контенту різними мовами. Вона просканує оригінальний контент і застосує ту саму таксономію до перекладеного контенту.','Please make a backup of your database before using these tools'=>'Будь ласка, зробіть резервну копію вашої бази даних перед використанням цих інструментів','There are <strong>%s product(s)</strong> in total.'=>'Усього є <strong>%s товар(ів)</strong>.','There are <strong>%s product(s)</strong> with variations.'=>'Є <strong>%s товар(ів)</strong> із варіаціями.','There are <strong>%s variation(s)</strong> in total.'=>'Усього є <strong>%s варіація(ій)</strong>.','Synchronize data into translations'=>'Синхронізувати дані в переклади','Synchronize product variations'=>'Синхронізувати варіації товарів','Synchronize products image galleries'=>'Синхронізувати галереї зображень товарів','Synchronize metadata for product categories (display type, thumbnail)'=>'Синхронізувати метадані для категорій товарів (тип відображення, мініатюра)','Synchronize stock for products and product variations'=>'Синхронізувати запаси для товарів та варіацій товарів','Fix multilingual information'=>'Виправити багатомовну інформацію','Fix incorrect or missing translation links for product variations'=>'Виправити неправильні або відсутні посилання на переклад для варіацій товарів','Fix product taxonomies'=>'Виправити таксономії товарів','Set product types as not translatable and delete unwanted translations'=>'Встановити типи товарів як такі, що не перекладаються, і видалити непотрібні переклади','Create missing translations for product attributes:'=>'Створити відсутні переклади для атрибутів товарів:','To translate product taxonomies, go to the %1$sTaxonomy Translation%2$s page.'=>'Щоб перекласти таксономії товарів, перейдіть на сторінку %1$sПереклад таксономій%2$s.','none'=>'немає','Fix missing product reviews'=>'Виправити відсутні відгуки про товари','Allow to translate missing product reviews'=>'Дозволити перекладати відсутні відгуки про товари','To translate product reviews, go to the %1$sTranslation Dashboard%2$s.'=>'Щоб перекласти відгуки про товари, перейдіть у %1$sПанель перекладу%2$s.','Cleanup tools'=>'Інструменти очищення','Remove unused custom fields from product and variation translations'=>'Видалити невикористовувані спеціальні поля з перекладів товарів та варіацій','Run the selected tools'=>'Запустити вибрані інструменти','Processing'=>'Обробка','WPML Multilingual & Multicurrency for WooCommerce settings'=>'Налаштування WPML Multilingual & Multicurrency for WooCommerce','%s items processed'=>'Оброблено елементів: %s','Processing...'=>'Обробка...','Completed'=>'Завершено','Something went wrong, please reload the page and try again'=>'Щось пішло не так, будь ласка, оновіть сторінку та спробуйте ще раз','Clear all colors'=>'Очистити всі кольори','Gray'=>'Сірий','White'=>'Білий','Blue'=>'Синій','Border'=>'Межа','Current currency font color'=>'Колір шрифту поточної валюти','Other currency font color'=>'Колір шрифту іншої валюти','Current currency background color'=>'Колір фону поточної валюти','Other currency background color'=>'Колір фону іншої валюти','Currency switcher style'=>'Стиль перемикача валют','Core'=>'Стандартний','Custom'=>'Спеціальний','Allowed HTML tags: <img> <span> <u> <strong> <em>'=>'Дозволені HTML-теги: <img> <span> <u> <strong> <em>','Template for currency switcher'=>'Шаблон для перемикача валют','Available parameters'=>'Доступні параметри','Default: %name% (%1$symbol%) - %2$code%'=>'Типово: %name% (%1$symbol%) - %2$code%','Hide more'=>'Приховати більше','You can customize the currency switcher template using these parameters:'=>'Ви можете налаштувати шаблон перемикача валют за допомогою цих параметрів:','%1$s: Full name of the currency (e.g., “Euro”).'=>'%1$s: Повна назва валюти (наприклад, «Euro»).','%1$s: Standard symbol representing the currency (e.g., “$” or “€”).'=>'%1$s: Стандартний символ, що представляє валюту (наприклад, «$» або «€»).','%1$s: Standard code representing the currency (e.g., USD for United States Dollar).'=>'%1$s: Стандартний код, що представляє валюту (наприклад, USD для долара США).','Additionally, you can use HTML tags %1$s(img, span, em, strong, u)%2$s to customize the output when the switcher style is set to %1$sList of currencies%2$s, %3$sin line with official HTML standards for the select tag%4$s.'=>'Крім того, ви можете використовувати HTML-теги %1$s(img, span, em, strong, u)%2$s, щоб налаштувати вигляд, коли для стилю перемикача встановлено %1$sСписок валют%2$s, %3$sвідповідно до офіційних стандартів HTML для тегу select%4$s.','Currency switcher colors'=>'Кольори перемикача валют','Color theme'=>'Колірна тема','Normal'=>'Звичайний','Hover'=>'При наведенні','Select a preset'=>'Виберіть пресет','Widget area'=>'Область віджетів','Widget title'=>'Заголовок віджета','-- Choose a widget area --'=>'-- Виберіть область віджетів --','Preview'=>'Попередній перегляд','Regular Price'=>'Звичайна ціна','Sale Price'=>'Ціна розпродажу','Multi-currency is enabled, but no secondary currencies have been set. %1$sAdd secondary currency%2$s.'=>'Мультивалютність увімкнено, але додаткові валюти не встановлено. %1$sДодати додаткову валюту%2$s.','Click to see the prices in the other currencies as they are currently shown on the front end.'=>'Натисніть, щоб побачити ціни в інших валютах, як вони зараз відображаються на сайті.','Show'=>'Показати','Hide'=>'Приховати','Enter prices in other currencies'=>'Введіть ціни в інших валютах','Hide prices in other currencies'=>'Приховати ціни в інших валютах','Determined automatically based on exchange rate'=>'Визначається автоматично на основі курсу валют','Schedule'=>'Розклад','Same as default currency'=>'Так само, як у типовій валюті','Set dates'=>'Встановити дати','Collapse'=>'Згорнути','From&hellip;'=>'Від&hellip;','To&hellip;'=>'До&hellip;','Please enter in a value less than the regular price'=>'Будь ласка, введіть значення, менше за звичайну ціну','never'=>'ніколи','Automatic Exchange Rates'=>'Автоматичні курси валют','Enable automatic exchange rates'=>'Увімкнути автоматичні курси валют','Exchange rates source'=>'Джерело курсів валют','Lifting charge'=>'Націнка','The lifting charge adjusts the exchange rate provided by the selected service before it is saved. The exchange rates displayed in the table above include the lifting charge.'=>'Націнка коригує курс валют, наданий вибраним сервісом, перед його збереженням. Курси валют, що відображаються в таблиці вище, включають націнку.','Exchange rate = %s exchange rate x (1 + lifting charge / 100)'=>'Курс валют = курс %s x (1 + націнка / 100)','API key (required)'=>'Ключ API (обов’язково)','Update frequency'=>'Частота оновлення','Update manually now'=>'Оновити вручну зараз','You have to save all settings before updating exchange rates'=>'Ви повинні зберегти всі налаштування перед оновленням курсів валют','Manually'=>'Вручну','Hourly'=>'Щогодини','Daily'=>'Щодня','Weekly on'=>'Щотижня у','Monthly on the'=>'Щомісяця','Enter API key'=>'Введіть ключ API','WARNING! Minor limitations include 1000 requests/month limit and EUR being the only available base currency for customers using a free account. If you need more than 1000 requests per month or want to use all 170 available base currencies, you’ll need to choose one of the paid plans starting at only $10 per month.'=>'УВАГА! Незначні обмеження включають ліміт 1000 запитів/місяць, а EUR є єдиною доступною базовою валютою для клієнтів з безкоштовним акаунтом. Якщо вам потрібно більше 1000 запитів на місяць або ви хочете використовувати всі 170 доступних базових валют, вам потрібно буде обрати один із платних планів за ціною від $10 на місяць.','Updating the exchange rates on an hourly basis generates around 744 API calls a month. Please check that your exchange rates source can accommodate this higher usage.'=>'Оновлення курсів валют щогодини генерує близько 744 API-запитів на місяць. Будь ласка, перевірте, чи ваше джерело курсів валют може забезпечити таке інтенсивне використання.','Last updated: %s'=>'Останнє оновлення: %s','Exchange rates updated successfully'=>'Курси валют успішно оновлено','Visit website'=>'Відвідати вебсайт','Enable/disable'=>'Увімкнути/вимкнути','The multi-currency mode cannot be enabled as a specific currency was not set. Go to the %1$sWooCommerce settings%2$s page and select the default currency for your store.'=>'Режим мультивалютності не може бути увімкнений, оскільки не встановлено конкретну валюту. Перейдіть на сторінку %1$sналаштувань WooCommerce%2$s і виберіть типову валюту для вашого магазину.','Enable the multicurrency mode'=>'Увімкнути режим мультивалютності','Multicurrency documentation'=>'Документація з мультивалютності','Custom prices'=>'Спеціальні ціни','Show only products with %1$scustom prices%2$s in secondary currencies'=>'Показувати лише товари зі %1$sспеціальними цінами%2$s у додаткових валютах','When enabled, products with prices based on the exchange rate are hidden'=>'Якщо увімкнено, товари з цінами на основі курсу валют будуть приховані','The changes you made will be lost if you navigate away from this page.'=>'Зміни, які ви зробили, будуть втрачені, якщо ви залишите цю сторінку.','At least one currency must be enabled for this language!'=>'Для цієї мови має бути увімкнена принаймні одна валюта!','Currency switcher options'=>'Параметри перемикача валют','All currency switchers in your site are affected by the settings in this section.'=>'Налаштування в цьому розділі впливають на всі перемикачі валют на вашому сайті.','Order of currencies'=>'Порядок валют','Additional CSS'=>'Додатковий CSS','Widget Currency Switcher'=>'Віджет перемикача валют','Product page Currency Switcher'=>'Перемикач валют на сторінці товару','Position'=>'Позиція','Actions'=>'Дії','Action'=>'Дія','Edit currency switcher'=>'Редагувати перемикач валют','Add a new currency switcher to a widget area'=>'Додати новий перемикач валют в область віджетів','Your theme does not support a currency switcher widget. Please %1$sadd your currency switcher%2$s using a shortcode or PHP.'=>'Ваша тема не підтримує віджет перемикача валют. Будь ласка, %1$sдодайте свій перемикач валют%2$s за допомогою шорткоду або PHP.','Currency switcher preview'=>'Попередній перегляд перемикача валют','Drag and drop the currencies to change their order'=>'Перетягніть валюти, щоб змінити їхній порядок','Show a currency switcher on the product page template'=>'Показувати перемикач валют у шаблоні сторінки товару','Edit Product Currency Switcher'=>'Редагувати перемикач валют товару','New Widget Area Currency Switcher'=>'Новий перемикач валют в області віджетів','Edit %s Currency Switcher'=>'Редагувати перемикач валют %s','Which product attributes should be translatable?'=>'Які атрибути товарів мають бути доступні для перекладу?','WPML allows you to %1$stranslate your product attributes%2$s. Some attributes, like the ones based on numbers and codes, can be universal and might not need to be translated.'=>'WPML дозволяє вам %1$sперекладати атрибути товарів%2$s. Деякі атрибути, наприклад ті, що базуються на числах і кодах, можуть бути універсальними і не потребувати перекладу.','Select which attributes in your store should be translatable:'=>'Виберіть, які атрибути у вашому магазині мають бути доступні для перекладу:','There are no attributes defined'=>'Атрибути не визначені','Continue'=>'Продовжити','Go back'=>'Назад','WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard'=>'WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard','Let\'s make your WooCommerce store multilingual'=>'Зробімо ваш магазин WooCommerce багатомовним','To get started, we need to set up the following:'=>'Для початку нам потрібно налаштувати наступне:','Create store pages in all your site\'s languages'=>'Створити сторінки магазину всіма мовами вашого сайту','Choose which product attributes you want to translate'=>'Вибрати атрибути товарів, які ви хочете перекласти','Set your translation options'=>'Встановити параметри перекладу','Decide if you want to add multiple currencies to your store'=>'Вирішити, чи хочете ви додати кілька валют у свій магазин','Let\'s continue'=>'Продовжити','I\'ll do the setup later'=>'Я виконаю налаштування пізніше','Do you want to add more currencies to your store?'=>'Бажаєте додати більше валют у свій магазин?','You will be able to:'=>'Ви зможете:','Add a currency switcher to your store'=>'Додати перемикач валют у свій магазин','Set exchange rates'=>'Встановити курси валют','Create custom pricing in each currency'=>'Створити спеціальні ціни в кожній валюті','And more!'=>'Та багато іншого!','Yes, enable multicurrency mode'=>'Так, увімкнути режим мультивалютності','No, use only one currency'=>'Ні, використовувати лише одну валюту','Make your store multilingual'=>'Зробіть свій магазин багатомовним','Set up %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s to translate your store and add more currencies.'=>'Налаштуйте %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s, щоб перекласти свій магазин і додати більше валют.','Start the Setup Wizard'=>'Запустити Setup Wizard','Click continue to create missing WooCommerce pages translate your store pages into the following languages:'=>'Натисніть «Продовжити», щоб створити відсутні сторінки WooCommerce та перекласти сторінки вашого магазину на такі мови:','Click continue to translate your store pages into the following languages:'=>'Натисніть «Продовжити», щоб перекласти сторінки вашого магазину на такі мови:','WPML automatically generates translated versions of default WooCommerce pages, such as Shop, Account, Checkout, and Cart.'=>'WPML автоматично створює перекладені версії типових сторінок WooCommerce, таких як Магазин, Акаунт, Оформлення замовлення та Кошик.','Configuration Warnings'=>'Попередження конфігурації','Your product permalink base is not translated to:'=>'База постійних посилань на товари не перекладена на:','Translate URLs'=>'Перекласти URL-адреси','Running WPML Multilingual & Multicurrency for WooCommerce with default language other than English.'=>'Запуск WPML Multilingual & Multicurrency for WooCommerce з типовою мовою, відмінною від англійської.','This may cause problems with URLs in different languages.'=>'Це може спричинити проблеми з URL-адресами різними мовами.','Change default language'=>'Змінити типову мову','There are some settings that require careful attention.'=>'Є деякі налаштування, які потребують пильної уваги.','Some settings from the WPML Multilingual & Multicurrency for WooCommerce wpml-config.xml file have been overwritten.'=>'Деякі налаштування з файлу wpml-config.xml плагіна WPML Multilingual & Multicurrency for WooCommerce були перезаписані.','You should check WPML configuration files added by other plugins or manual settings on the %s section.'=>'Вам слід перевірити конфігураційні файли WPML, додані іншими плагінами, або ручні налаштування в розділі %s.','Multilingual Content Setup'=>'Налаштування багатомовного контенту','Media'=>'Медіафайли','%s is not active.'=>'%s не активний.','%s is not required in order to run WPML Multilingual & Multicurrency for WooCommerce but it’s recommended if you want to use separate product images and galleries for different languages.'=>'%s не є обов’язковим для роботи WPML Multilingual & Multicurrency for WooCommerce, але він рекомендований, якщо ви хочете використовувати окремі зображення та галереї товарів для різних мов.','%s is installed and active.'=>'%s встановлено та активовано.','Secondary currencies: %s'=>'Додаткові валюти: %s','Multi-currency is not enabled.'=>'Мультивалютність не увімкнено.','Add Currencies'=>'Додати валюти','Products Missing Translations'=>'Товари, для яких відсутні переклади','%1$d %2$s translation missing.'=>'Відсутній %1$d переклад для мови %2$s.','%1$d %2$s translations missing.'=>'Відсутні %1$d переклади для мови %2$s.','Right now, there are no products needing translation.'=>'Наразі немає товарів, що потребують перекладу.','Plugins Status'=>'Статус плагінів','%s is set up.'=>'%s налаштовано.','%s is not set up.'=>'%s не налаштовано.','WPML Multilingual & Multicurrency for WooCommerce depends on several plugins to work. If any required plugin is missing, you should install and activate it.'=>'WPML Multilingual & Multicurrency for WooCommerce залежить від кількох плагінів для роботи. Якщо будь-який необхідний плагін відсутній, вам слід встановити та активувати його.','WooCommerce Store Pages'=>'Сторінки магазину WooCommerce','To run a multilingual e-commerce site, you need to have the WooCommerce shop pages translated to all the site\'s languages. Once all the pages are installed you can add the translations for them from this menu.'=>'Щоб запустити багатомовний сайт електронної комерції, вам потрібно перекласти сторінки магазину WooCommerce на всі мови сайту. Після встановлення всіх сторінок ви зможете додати для них переклади з цього меню.','One or more WooCommerce pages have not been created.'=>'Одну або кілька сторінок WooCommerce не було створено.','Install WooCommerce Pages'=>'Встановити сторінки WooCommerce','WooCommerce store pages do not exist for these languages:'=>'Сторінки магазину WooCommerce не існують для цих мов:','Create missing translations'=>'Створити відсутні переклади','These pages are currently being translated by translators via WPML: '=>'Ці сторінки зараз перекладаються перекладачами через WPML: ','WooCommerce store pages are translated to all the site\'s languages.'=>'Сторінки магазину WooCommerce перекладені на всі мови сайту.','Taxonomies Missing Translations'=>'Таксономії з відсутніми перекладами','To run a fully translated site, you should translate all taxonomy terms. Some store elements, such as variations, depend on taxonomy translation.'=>'Щоб запустити повністю перекладений сайт, вам слід перекласти всі терміни таксономії. Деякі елементи магазину, як-от варіації, залежать від перекладу таксономії.','%s do not require translation.'=>'%s не потребують перекладу.','This taxonomy requires translation.'=>'Ця таксономія потребує перекладу.','%1$d %2$s is missing translations.'=>'Для %2$s відсутній %1$d переклад.','%1$d %2$s are missing translations.'=>'Для %2$s відсутні %1$d переклади.','Translate %s'=>'Перекласти %s','This taxonomy does not require translation.'=>'Ця таксономія не потребує перекладу.','All %s are translated.'=>'Усі %s перекладені.','Right now, there are no taxonomy terms needing translation.'=>'Наразі немає термінів таксономії, що потребують перекладу.','To configure product taxonomies or attributes as translatable or not translatable, go to the %1$sMultilingual Content Setup%2$s'=>'Щоб налаштувати таксономії або атрибути товарів як такі, що підлягають або не підлягають перекладу, перейдіть у %1$sНалаштування багатомовного вмісту%2$s','Original'=>'Оригінал','Translation to'=>'Переклад на','Product Shop Base'=>'База сторінки магазину','Original language'=>'Мова оригіналу','Update translation'=>'Оновити переклад','Add translation'=>'Додати переклад','Edit translation'=>'Редагувати переклад','This page allows you to translate all strings that are being used by WooCommerce in building different type of urls. Translating them enables you to have fully localized urls that match the language of the pages.'=>'Ця сторінка дозволяє перекласти всі рядки, які використовуються WooCommerce для створення різних типів URL-адрес. Їх переклад дозволяє мати повністю локалізовані URL-адреси, що відповідають мові сторінок.','You can enter or edit your default values on the %1$sPermalinks settings%2$s page or, for the endpoints, on the WooCommerce %3$sAdvanced settings%4$s page.'=>'Ви можете ввести або відредагувати ваші типові значення на сторінці %1$sналаштування постійних посилань%2$s або, для кінцевих точок, на сторінці %3$sдодаткових налаштувань%4$s WooCommerce.','permalinks settings'=>'налаштування постійних посилань','Account settings'=>'Налаштування акаунта','Slug type'=>'Тип частини посилання','Original Slug'=>'Оригінальна частина посилання','Shop page'=>'Сторінка магазину','Product base'=>'База товарів','Product category base'=>'База категорій товарів','Product tag base'=>'База тегів товарів','Product attribute base'=>'База атрибутів товарів','Attribute slug: %s'=>'Частина посилання атрибута: %s','Product'=>'Товар','Slug'=>'Частина посилання','Content / Description'=>'Вміст / Опис','Excerpt'=>'Уривок','Purchase note'=>'Примітка до покупки','Images'=>'Зображення','Custom Product attributes'=>'Спеціальні атрибути товару','Value(s)'=>'Значення','Custom Fields'=>'Спеціальні поля','Variations data'=>'Дані варіацій','Download Files for Variation #%s'=>'Файли для завантаження для варіації №%s','Download Files'=>'Файли для завантаження','File URL'=>'URL-адреса файлу','External Product'=>'Зовнішній товар','Product url'=>'URL-адреса товару','Button text'=>'Текст кнопки','Changes in these translations will affect terms in general! ( Not only for this product )'=>'Зміни в цих перекладах вплинуть на терміни загалом! ( Не лише для цього товару )','Content, title, and excerpt are empty.'=>'Вміст, заголовок та уривок порожні.']];